'use client';

import { useSearchParams } from 'next/navigation';
import { useEffect, useState } from 'react';

type Question = {
    question: string;
    answer: number;
    marking_polarity: boolean;
};

type ResultData = {
    score: number;
    interpretation: string;
    questions: Question[];
};

export default function ResultsPage() {
    const searchParams = useSearchParams();
    const [result, setResult] = useState<ResultData | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const scaleLabels = [
        'Not at all true',
        'Mostly not true',
        'Slightly not true',
        'Neutral',
        'Slightly true',
        'Mostly true',
        'Very true',
    ];

    useEffect(() => {
        try {
            const data = searchParams.get('data');
            if (!data) {
                throw new Error('No result data found');
            }
            const decoded = JSON.parse(decodeURIComponent(data));
            setResult(decoded);
        } catch (err) {
            setError('Failed to load results. Please take the assessment again.');
            console.error('Error parsing result data:', err);
        } finally {
            setIsLoading(false);
        }
    }, [searchParams]);

    if (isLoading) {
        return (
            <div className="flex min-h-screen items-center justify-center">
                <div className="text-center">
                    <div className="mx-auto h-12 w-12 animate-spin rounded-full border-b-2 border-blue-500"></div>
                    <p className="mt-4 text-gray-600">Loading your results...</p>
                </div>
            </div>
        );
    }

    if (error || !result) {
        return (
            <div className="flex min-h-screen items-center justify-center px-6 py-20">
                <div className="mx-auto max-w-2xl overflow-hidden rounded-2xl border-2 border-gray-200 bg-white/40 p-8 text-center shadow-xl backdrop-blur-lg">
                    <h2 className="mb-4 text-2xl font-bold text-red-600">Error Loading Results</h2>
                    <p className="mb-6 text-gray-600">{error || 'Unable to load assessment results.'}</p>
                    <a
                        href="/IRS-Calculate_Inner_restlessnes_score"
                        className="inline-flex items-center justify-center rounded-md border border-transparent bg-blue-600 px-6 py-2.5 text-base font-medium text-white shadow-sm transition-colors hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:outline-none"
                    >
                        Take Assessment Again
                    </a>
                </div>
            </div>
        );
    }

    const { score, interpretation, questions } = result;
    const percentage = score > 0 ? Math.round(((score - 24) / (168 - 24)) * 100) : 0;

    return (
        <div className="flex min-h-screen items-center justify-center px-6 py-20">
            <div className="mx-auto max-w-2xl overflow-hidden rounded-2xl border-2 border-gray-200 bg-white/40 shadow-xl backdrop-blur-lg">
                <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-6 text-white shadow-md">
                    <h1 className="text-2xl font-bold">Your Assessment Results</h1>
                    <p className="opacity-90">Internal Restlessness Scale (IRS) Assessment</p>
                </div>

                <div className="bg-gradient-to-br from-white/40 to-white/20 p-6">
                    <div className="mb-8 text-center">
                        <div className="mb-2 text-sm font-medium text-gray-500">Your Score</div>
                        <div className="mb-1 text-5xl font-bold text-blue-600">{score}</div>
                        <div className="mb-6 text-sm text-gray-500">
                            out of 168 (maximum possible score)
                        </div>

                        <div className="mx-auto h-4 w-full max-w-md overflow-hidden rounded-full bg-gray-200">
                            <div
                                className="h-4 rounded-full bg-blue-600 transition-all duration-1000 ease-out"
                                style={{ width: `${percentage}%` }}
                            ></div>
                        </div>
                    </div>

                    <div className="mb-8">
                        <h3 className="mb-3 text-lg font-medium text-gray-900">
                            Score Interpretation
                        </h3>
                        <div className="rounded-xl border-2 border-gray-100 bg-white/70 p-4 backdrop-blur-sm">
                            <p className="text-gray-800">{interpretation}</p>

                            <div className="mt-4 text-sm text-gray-600">
                                <div className="grid grid-cols-1 gap-2">
                                    <div className="flex justify-between">
                                        <span>24-69:</span>
                                        <span className="font-medium">
                                            Typical range for neurotypical adults
                                        </span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span>70-89:</span>
                                        <span className="font-medium">
                                            Borderline range, may indicate subclinical symptoms
                                        </span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span>90-110:</span>
                                        <span className="font-medium">
                                            Typical range for adults with ADHD
                                        </span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span>110-168:</span>
                                        <span className="font-medium">
                                            High range, often seen in significant ADHD symptoms
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="mb-8">
                        <h3 className="mb-3 text-lg font-medium text-gray-900">
                            Your Responses
                        </h3>
                        <div className="max-h-96 space-y-4 overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-blue-200 scrollbar-track-transparent">
                            {questions.map((question, index) => (
                                <div
                                    key={index}
                                    className="mx-2 rounded-xl border-2 border-gray-100 bg-white/60 p-4 shadow-sm backdrop-blur-sm"
                                >
                                    <div className="flex items-start">
                                        <span className="mr-3 inline-flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full bg-blue-100 text-sm font-medium text-blue-800">
                                            {index + 1}
                                        </span>
                                        <div className="flex-1">
                                            <p className="mb-2 text-sm font-medium text-gray-800">
                                                {question.question}
                                            </p>
                                            <div className="mt-2">
                                                <div className="mb-1 flex justify-between text-xs text-gray-500">
                                                    <span>Not at all true</span>
                                                    <span>Very true</span>
                                                </div>
                                                <div className="h-2 w-full overflow-hidden rounded-full bg-gray-200">
                                                    <div
                                                        className="h-full bg-blue-600 transition-all duration-500 ease-out"
                                                        style={{
                                                            width: `${((question.answer || 0) / 7) * 100}%`,
                                                        }}
                                                    ></div>
                                                </div>
                                                <div className="mt-1 text-right text-sm font-medium text-blue-600">
                                                    {question.answer !== null
                                                        ? scaleLabels[question.answer - 1]
                                                        : 'Not answered'}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="rounded-lg border-t-2 border-r-2 border-b-2 border-l-4 border-yellow-100 border-yellow-400 bg-yellow-50/80 p-4 backdrop-blur-sm">
                        <div className="flex">
                            <div className="flex-shrink-0">
                                <svg
                                    className="h-5 w-5 text-yellow-400"
                                    xmlns="http://www.w3.org/2000/svg"
                                    viewBox="0 0 20 20"
                                    fill="currentColor"
                                >
                                    <path
                                        fillRule="evenodd"
                                        d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z"
                                        clipRule="evenodd"
                                    />
                                </svg>
                            </div>
                            <div className="ml-3">
                                <h3 className="text-sm font-medium text-yellow-800">
                                    Important Note
                                </h3>
                                <div className="mt-2 text-sm text-yellow-700">
                                    <p>
                                        This assessment is not a diagnostic tool. Only a qualified
                                        healthcare professional can diagnose ADHD or any other medical
                                        condition. This tool is for informational purposes only.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="mt-8 flex justify-center">
                        <a
                            href="/IRS-Calculate_Inner_restlessnes_score"
                            className="inline-flex items-center justify-center rounded-md border border-transparent bg-blue-600 px-6 py-2.5 text-base font-medium text-white shadow-sm transition-colors hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:outline-none"
                        >
                            <svg
                                className="mr-2 -ml-1 h-5 w-5"
                                xmlns="http://www.w3.org/2000/svg"
                                viewBox="0 0 20 20"
                                fill="currentColor"
                            >
                                <path
                                    fillRule="evenodd"
                                    d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 010 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z"
                                    clipRule="evenodd"
                                />
                            </svg>
                            Retake Assessment
                        </a>
                    </div>
                </div>
            </div>
        </div>
    );
}
